async function translateTitleKo(title){
  if(!title||title.startsWith("샘플:"))return title.replace("샘플:","예시 해석:");
  const cached=localStorage.getItem("koTitleV4:"+title);
  if(cached)return cached;
  const fallback=fallbackTranslate(title)||fallbackTranslateRules(title);
  const apis=[
    "https://api.mymemory.translated.net/get?q="+encodeURIComponent(title)+"&langpair=en|ko",
    "https://translate.googleapis.com/translate_a/single?client=gtx&sl=en&tl=ko&dt=t&q="+encodeURIComponent(title)
  ];
  for(const url of apis){
    try{
      const res=await fetchWithTimeout(url,null,4500);
      if(!res.ok)continue;
      const data=await res.json();
      let translated="";
      if(url.includes("mymemory"))translated=data&&data.responseData&&data.responseData.translatedText||"";
      else translated=Array.isArray(data)&&Array.isArray(data[0])?data[0].map(function(part){return part[0]||""}).join(""):"";
      translated=stripHtml(translated).replace(/\s+/g," ").trim();
      if(translated&&translated.toLowerCase()!==title.toLowerCase()){
        const englishWords=(translated.match(/[A-Za-z]{3,}/g)||[]).filter(function(word){return !["IonQ","IONQ","NYSE","NASDAQ","SEALSQ","WISeKey","Quantisimo","GigCapital8","LAES","LOI","AI"].includes(word)}).length;
        const originalWords=(title.match(/[A-Za-z]{3,}/g)||[]).length;
        if(englishWords<=Math.max(2,Math.floor(originalWords*0.35))){
          localStorage.setItem("koTitleV4:"+title,translated);
          return translated;
        }
      }
    }catch(e){console.warn("translation api unavailable",e)}
  }
  return fallback&&fallback!==title?fallback:title;
}
