function nextMarketDays(count){const days=[];const cursor=new Date();cursor.setHours(0,0,0,0);while(days.length<count){const day=cursor.getDay();if(day!==0&&day!==6)days.push(new Date(cursor));cursor.setDate(cursor.getDate()+1)}return days}
function eventForDate(date){return MARKET_EVENT_PATTERNS.find(function(item){return item.match(date)})||MARKET_EVENT_PATTERNS[0]}
function renderMarketCalendar(){const grid=document.querySelector(".calendar-grid");if(!grid)return;const today=new Date();grid.textContent="";nextMarketDays(4).forEach(function(date){const event=eventForDate(date);const article=document.createElement("article");article.className="calendar-day"+(isSameLocalDate(date,today)?" today":"");const month=date.getMonth()+1;const day=date.getDate();article.innerHTML='<time datetime="'+localDateAttr(date)+'"><span>'+month+'월 '+day+'일</span><strong>'+date.toLocaleDateString("ko-KR",{weekday:"short"})+'</strong></time><div><b>'+event.title+'</b><p>'+event.body+'</p></div>';grid.append(article)})}
async function renderValuation(){const ticker=state.ticker;if(!els.valuationGrid)return;els.valuationAsOf.textContent="데이터 불러오는 중";renderValuationShell("...");try{const data=await fetchValuationData(ticker);if(state.ticker!==ticker)return;renderValuationItems(data)}catch(e){console.warn("valuation data unavailable",e);if(state.ticker!==ticker)return;els.valuationAsOf.textContent=errorMessage(e).slice(0,80);renderValuationShell("-")}}
function renderMetrics(){const items=state.news.filter(function(x){return x.ticker===state.ticker});els.metricNews.textContent=items.length;els.metricPositive.textContent=items.filter(function(x){return x.sentiment>0}).length;els.metricRisk.textContent=items.filter(function(x){return x.risk>0}).length;const heat=items.reduce(function(s,x){return s+x.importance},0)/Math.max(1,items.length);els.metricHeat.textContent=Math.min(99,Math.round(heat))}
function renderAnalysis(){const items=state.news.filter(function(x){return x.ticker===state.ticker});const avg=items.reduce(function(s,x){return s+x.importance},0)/Math.max(1,items.length);const boost=items.reduce(function(s,x){return s+x.sentiment*6},0);const score=Math.max(20,Math.min(95,Math.round(avg+boost)));els.analysisTitle.textContent=state.ticker+" 종합 점수";els.analysisSummary.textContent=items.length?items.length+"개 뉴스 기준입니다. 뉴스 빈도, 중요도, 호재·리스크 신호를 합산했습니다.":"아직 분석할 뉴스가 없습니다.";els.scoreRing.textContent=score;els.scoreRing.style.background="conic-gradient(var(--green) "+score+"%, #e3e9e5 0)";const factors=[["계약/고객",KEYWORDS.contract],["기술 로드맵",KEYWORDS.tech],["재무/밸류에이션",KEYWORDS.finance],["리스크",KEYWORDS.risk]].map(function(pair){const hits=items.filter(function(item){return pair[1].some(function(w){return item.title.toLowerCase().includes(w)})}).length;return{label:pair[0],hits:hits,value:Math.min(100,25+hits*25)}});els.factorList.textContent="";factors.forEach(function(f){const card=document.createElement("article");card.className="factor";card.innerHTML='<header><strong>'+f.label+'</strong><span>'+f.hits+'건</span></header><div class="bar"><span style="--value:'+f.value+'%"></span></div>';els.factorList.append(card)})}
function renderAlerts(){const items=state.news.filter(function(item){return item.ticker===state.ticker&&item.importance>=Number(els.alertThreshold.value)}).slice(0,5);els.alertPreview.textContent=JSON.stringify({ticker:state.ticker,generatedAt:new Date().toISOString(),channel:"IonQ Radar",webhook:els.webhookTarget.value||null,items:items.map(function(item){return{title:item.translated,summary:item.summary,link:item.link,importance:item.importance}})},null,2)}

function officialLink(label,url){const a=document.createElement("a");a.href=url;a.target="_blank";a.rel="noreferrer";a.textContent=label;return a}
function officialSourcesForTicker(ticker){if(OFFICIAL_SOURCES[ticker])return OFFICIAL_SOURCES[ticker];const encoded=encodeURIComponent(ticker);const news="https://news.google.com/search?q="+encoded+"%20stock";const sec="https://www.sec.gov/edgar/search/#/q="+encoded;const x="https://x.com/search?q="+encoded+"&src=typed_query&f=live";return{name:ticker,site:news,news:news,ir:sec,x:x,twitter:x,search:x,cards:[{pill:"News",tone:"",title:ticker+" 최신 뉴스 검색",body:"입력한 티커의 최신 보도와 시장 뉴스를 확인합니다.",url:news},{pill:"SEC",tone:"red",title:ticker+" SEC 공시 검색",body:"미국 증권거래위원회에서 해당 티커 관련 공시를 확인합니다.",url:sec},{pill:"X",tone:"blue",title:ticker+" 실시간 X 검색",body:"티커 관련 회사 발표와 시장 반응을 실시간으로 검색합니다.",url:x}]}}
function renderOfficialSources(){const ticker=state.ticker||"IONQ";const data=officialSourcesForTicker(ticker);if(!els.officialActions)return;els.officialSubtitle.textContent=data.name+" 공식 홈페이지, IR 공지, 공식 X, 주요 메시지를 한 화면에서 확인합니다.";els.officialActions.textContent="";els.officialActions.append(officialLink("뉴스룸",data.news),officialLink("공식 X",data.x),officialLink("IR 공지",data.ir));els.officialCardList.textContent="";data.cards.forEach(function(card){const article=document.createElement("article");article.className="official-card";article.innerHTML='<a href="'+card.url+'" target="_blank" rel="noreferrer"><span class="official-pill '+card.tone+'">'+card.pill+'</span><h3>'+card.title+'</h3><p>'+card.body+'</p></a>';els.officialCardList.append(article)});els.officialTimelineTitle.textContent=data.name+" 공식 X 타임라인";els.officialTimelineOpen.href=data.x;els.officialShortcuts.textContent="";els.officialShortcuts.append(officialLink("공식 계정",data.x),officialLink("실시간 검색",data.search));els.officialTimelineBox.textContent="";const timeline=document.createElement("a");timeline.className="twitter-timeline";timeline.dataset.height="620";timeline.dataset.chrome="noheader nofooter transparent";timeline.href=data.twitter;timeline.textContent="Tweets by "+data.name;els.officialTimelineBox.append(timeline);if(window.twttr&&window.twttr.widgets)window.twttr.widgets.load(els.officialTimelineBox)}
function loadTradingViewScript(container,src,config){if(!container)return;container.textContent="";const inner=document.createElement("div");inner.className="tradingview-widget-container__widget";container.append(inner);const script=document.createElement("script");script.type="text/javascript";script.src=src;script.async=true;script.text=JSON.stringify(config);container.append(script)}
