function scheduleRefresh(){clearTimeout(state.refreshTimer);clearInterval(state.countdownTimer);const minutes=Number(els.refreshMinutes.value||15);state.nextRefreshAt=Date.now()+minutes*60000;state.refreshTimer=setTimeout(collectNews,minutes*60000);state.countdownTimer=setInterval(updateCountdown,1000);updateCountdown()}
function updateCountdown(){const ms=Math.max(0,state.nextRefreshAt-Date.now());const m=Math.floor(ms/60000);const s=Math.floor((ms%60000)/1000);els.nextRefresh.value=m+":"+String(s).padStart(2,"0")}
function bindEvents(){$$(".tabs button").forEach(function(button){button.addEventListener("click",function(){$$(".tabs button").forEach(function(item){item.classList.toggle("active",item===button)});$$(".view").forEach(function(view){view.classList.toggle("active",view.id===button.dataset.view)})})});$$(".filters button").forEach(function(button){button.addEventListener("click",function(){state.filter=button.dataset.filter;$$(".filters button").forEach(function(item){item.classList.toggle("active",item===button)});renderNews()})});els.searchInput.addEventListener("input",renderNews);els.refreshNow.addEventListener("click",applyTicker);els.refreshMinutes.addEventListener("change",function(){saveSettings();scheduleRefresh()});[els.rssSources,els.emailTarget,els.webhookTarget,els.alertThreshold,els.aiEndpoint,els.valuationApiKey,els.alphaVantageApiKey,els.finnhubApiKey].filter(Boolean).forEach(function(el){el.addEventListener("input",function(){saveSettings();if(el===els.valuationApiKey||el===els.alphaVantageApiKey||el===els.finnhubApiKey){if(els.valuationApiKey)els.valuationApiKey.value=normalizeApiKey(els.valuationApiKey.value);if(els.alphaVantageApiKey)els.alphaVantageApiKey.value=normalizeApiKey(els.alphaVantageApiKey.value);if(els.finnhubApiKey)els.finnhubApiKey.value=normalizeApiKey(els.finnhubApiKey.value);Object.keys(localStorage).filter(function(key){return key.indexOf("valuationDataV")===0}).forEach(function(key){localStorage.removeItem(key)});saveSettings();renderValuation();updateMarketWidgets()}else renderAlerts()})});els.makeEmail.addEventListener("click",function(){const subject=encodeURIComponent("[Stock Radar] "+state.ticker+" 주요 뉴스");const body=encodeURIComponent(els.alertPreview.textContent);window.location.href="mailto:"+els.emailTarget.value+"?subject="+subject+"&body="+body});els.copyWebhook.addEventListener("click",async function(){await navigator.clipboard.writeText(els.alertPreview.textContent);els.refreshState.textContent="웹훅 메시지를 복사했습니다"})}
function applyTicker(){const ticker=normalizeTicker(els.tickerSelect.value);if(!ticker){els.tickerSelect.value=state.ticker;els.refreshState.textContent="티커를 입력해 주세요";return}els.tickerSelect.value=ticker;state.ticker=ticker;els.refreshState.textContent=ticker+" 조회 중";collectNews()}
